3	import (
4		"context"
5		"encoding/base64"
6		"encoding/json"
7		"log/slog"
8		"net/http"
9		"os"
10		"strings"
11		"sync"
12	
13		"github.com/golang-jwt/jwt/v5"
14		"github.com/MicahParks/keyfunc/v3"
15	)
16	
17	type ctxKey string
18	
19	const tenantCtxKey ctxKey = "tenant_id"
20	
21	var (
22		jwksOnce sync.Once
23		jwksFunc jwt.Keyfunc
24	)
25	
26	func initJWKS() {
27		jwksURL := os.Getenv("WORKOS_JWKS_URL")
28		if jwksURL == "" {
29			return
30		}
31	
32		k, err := keyfunc.NewDefault([]string{jwksURL})
33		if err != nil {
34			slog.Error("failed to initialize JWKS", "error", err, "url", jwksURL)
35			return
36		}
37		jwksFunc = k.Keyfunc
38		slog.Info("JWKS initialized", "url", jwksURL)
39	}
40	
41	func withTenantAuth(next http.Handler) http.Handler {
42		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
43			jwksOnce.Do(initJWKS)
44	
45			tenantID := ""
46	
47			if auth := r.Header.Get("Authorization"); strings.HasPrefix(auth, "Bearer ") {
48				token := strings.TrimPrefix(auth, "Bearer ")
49	
50				if jwksFunc != nil {
51					if tid := verifyAndExtractTenant(token); tid != "" {
52						tenantID = tid
53					}
54				} else {
55					if tid := extractTenantFromJWT(token); tid != "" {
56						tenantID = tid
57					}
58				}
59			}
60	
61			if tenantID == "" {
62				if tid := r.Header.Get("X-Tenant-ID"); tid != "" {
63					tenantID = tid
64				}
65			}
66	
67			if tenantID == "" {
68				tenantID = "default"
69			}
70	
71			ctx := context.WithValue(r.Context(), tenantCtxKey, tenantID)
72			next.ServeHTTP(w, r.WithContext(ctx))
73		})
74	}
75	
76	func verifyAndExtractTenant(tokenString string) string {
77		token, err := jwt.Parse(tokenString, jwksFunc)
78		if err != nil {
79			slog.Debug("jwt verification failed", "error", err)
80			return ""
81		}
82	
83		claims, ok := token.Claims.(jwt.MapClaims)
84		if !ok {
85			return ""
86		}
87	
88		if tid, ok := claims["org_id"].(string); ok && tid != "" {
89			return tid
90		}
91		if tid, ok := claims["tenant_id"].(string); ok && tid != "" {
92			return tid
93		}
94		return ""
95	}
96	
97	func tenantFromCtx(r *http.Request) string {
98		if tid, ok := r.Context().Value(tenantCtxKey).(string); ok && tid != "" {
99			return tid
100		}
101		return "default"
102	}
103	
104	func extractTenantFromJWT(token string) string {
105		parts := strings.Split(token, ".")
106		if len(parts) != 3 {
107			return ""
108		}
109	
110		payload, err := base64.RawURLEncoding.DecodeString(parts[1])
111		if err != nil {
112			return ""
113		}
114	
115		var claims struct {
116			TenantID string `json:"tenant_id"`
117			OrgID    string `json:"org_id"`
118		}
119		if err := json.Unmarshal(payload, &claims); err != nil {
120			return ""
121		}
122	
123		if claims.TenantID != "" {
124			return claims.TenantID
125		}
126		return claims.OrgID
127	}
