32	func (h *handler) handleCreateCheckout(w http.ResponseWriter, r *http.Request) {
33		tenantID := tenantFromCtx(r)
34	
35		priceID := os.Getenv("STRIPE_PRO_PRICE_ID")
36		if priceID == "" {
37			http.Error(w, "billing not configured", http.StatusServiceUnavailable)
38			return
39		}
40	
41		successURL := os.Getenv("DASHBOARD_URL")
42		if successURL == "" {
43			successURL = "http://localhost:3000"
44		}
45	
46		params := &stripe.CheckoutSessionParams{
47			Mode: stripe.String(string(stripe.CheckoutSessionModeSubscription)),
48			LineItems: []*stripe.CheckoutSessionLineItemParams{
49				{
50					Price:    stripe.String(priceID),
51					Quantity: stripe.Int64(1),
52				},
53			},
54			SuccessURL: stripe.String(successURL + "/billing?status=success"),
55			CancelURL:  stripe.String(successURL + "/billing?status=cancelled"),
56			ClientReferenceID: stripe.String(tenantID),
57			Metadata: map[string]string{
58				"tenant_id": tenantID,
59			},
60		}
61	
62		s, err := session.New(params)
63		if err != nil {
64			h.logger.Error("stripe checkout creation failed", "error", err)
65			http.Error(w, "checkout failed", http.StatusInternalServerError)
66			return
67		}
68	
69		w.Header().Set("Content-Type", "application/json")
70		json.NewEncoder(w).Encode(map[string]string{
71			"checkout_url": s.URL,
72		})
73	}
