75	func (h *handler) handleStripeWebhook(w http.ResponseWriter, r *http.Request) {
76		body, err := io.ReadAll(io.LimitReader(r.Body, 65536))
77		if err != nil {
78			http.Error(w, "read error", http.StatusBadRequest)
79			return
80		}
81	
82		endpointSecret := os.Getenv("STRIPE_WEBHOOK_SECRET")
83		if endpointSecret == "" {
84			h.logger.Warn("stripe webhook secret not configured")
85			w.WriteHeader(http.StatusOK)
86			return
87		}
88	
89		event, err := webhook.ConstructEvent(body, r.Header.Get("Stripe-Signature"), endpointSecret)
90		if err != nil {
91			h.logger.Error("stripe webhook signature verification failed", "error", err)
92			http.Error(w, "invalid signature", http.StatusBadRequest)
93			return
94		}
95	
96		switch event.Type {
97		case "checkout.session.completed":
98			var cs stripe.CheckoutSession
99			if err := json.Unmarshal(event.Data.Raw, &cs); err != nil {
100				h.logger.Error("unmarshal checkout session", "error", err)
101				break
102			}
103			tenantID := cs.Metadata["tenant_id"]
104			if tenantID == "" {
105				tenantID = cs.ClientReferenceID
106			}
107			if tenantID != "" {
108				h.logger.Info("subscription activated", "tenant", tenantID)
109				if err := h.store.SetBillingStatus(r.Context(), tenantID, "pro", "active"); err != nil {
110					h.logger.Error("set billing status failed", "error", err)
111				}
112			}
113	
114		case "customer.subscription.deleted":
115			var sub stripe.Subscription
116			if err := json.Unmarshal(event.Data.Raw, &sub); err != nil {
117				break
118			}
119			tenantID := sub.Metadata["tenant_id"]
120			if tenantID != "" {
121				h.logger.Info("subscription cancelled", "tenant", tenantID)
122				if err := h.store.SetBillingStatus(r.Context(), tenantID, "free", "cancelled"); err != nil {
123					h.logger.Error("set billing status failed", "error", err)
124				}
125			}
126		}
127	
128		w.WriteHeader(http.StatusOK)
129	}
