3	import { useEffect, useRef, useState, useCallback } from "react";
4	
5	export interface LiveMetrics {
6	  tokens_saved_today: number;
7	  events_today: number;
8	  active_sessions: number;
9	  timestamp: number;
10	}
11	
12	const WS_URL =
13	  process.env.NEXT_PUBLIC_WS_URL || "ws://localhost:8080/v1/ws";
14	const TENANT_ID = process.env.NEXT_PUBLIC_TENANT_ID || "demo-tenant";
15	
16	export function useLiveMetrics() {
17	  const [metrics, setMetrics] = useState<LiveMetrics | null>(null);
18	  const [connected, setConnected] = useState(false);
19	  const wsRef = useRef<WebSocket | null>(null);
20	  const retriesRef = useRef(0);
21	  const maxRetries = 10;
22	
23	  const connect = useCallback(() => {
24	    if (wsRef.current?.readyState === WebSocket.OPEN) return;
25	
26	    const url = `${WS_URL}?tenant_id=${TENANT_ID}`;
27	    const ws = new WebSocket(url);
28	    wsRef.current = ws;
29	
30	    ws.onopen = () => {
31	      setConnected(true);
32	      retriesRef.current = 0;
33	    };
34	
35	    ws.onmessage = (event) => {
36	      try {
37	        const data = JSON.parse(event.data) as LiveMetrics;
38	        setMetrics((prev) => {
39	          if (!prev) return data;
40	          return {
41	            tokens_saved_today:
42	              prev.tokens_saved_today + data.tokens_saved_today,
43	            events_today: prev.events_today + data.events_today,
44	            active_sessions: data.active_sessions || prev.active_sessions,
45	            timestamp: data.timestamp,
46	          };
47	        });
48	      } catch {
49	        // ignore malformed messages
50	      }
51	    };
52	
53	    ws.onclose = () => {
54	      setConnected(false);
55	      wsRef.current = null;
56	      if (retriesRef.current < maxRetries) {
57	        const delay = Math.min(1000 * 2 ** retriesRef.current, 30000);
58	        retriesRef.current++;
59	        setTimeout(connect, delay);
60	      }
61	    };
62	
63	    ws.onerror = () => {
64	      ws.close();
65	    };
66	  }, []);
67	
68	  useEffect(() => {
69	    connect();
70	    return () => {
71	      wsRef.current?.close();
72	    };
73	  }, [connect]);
74	
75	  return { metrics, connected };
76	}
